/** Archived issues whose `archived_at` is at or before `cutoff`, every project. */
export async function listIssuesArchivedBefore(
  orgId: OrgId,
  cutoff: IsoTimestamp,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        isNotNull(issues.archivedAt),
        lte(issues.archivedAt, cutoff),
      ),
    )
    .all();
  return rows.map((row) => toIssue(row));
}

export interface PurgedIssue {
  readonly commentIds: readonly string[];
  readonly attachmentSizes: readonly number[];
}

/**
 * Deletes an issue for good with its label links, comments and attachments.
 * The project's high-water mark keeps its number from being reused.
 */
export async function purgeIssue(
  orgId: OrgId,
  issueId: IssueId,
): Promise<PurgedIssue | null> {
  const db = getDb();
  return db.transaction((tx) => {
    const row = tx
      .select()
      .from(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .get();
    if (!row) return null;

    raiseHighWater(row.orgId, row.projectId, row.number);

    const commentRows = tx
      .select({ id: comments.id })
      .from(comments)
      .where(
        and(orgPredicate(comments.orgId, orgId), eq(comments.issueId, issueId)),
      )
      .all();
    const attachmentRows = tx
      .select({ sizeBytes: attachments.sizeBytes })
      .from(attachments)
      .where(
        and(
          orgPredicate(attachments.orgId, orgId),
          eq(attachments.issueId, issueId),
        ),
      )
      .all();

    tx.delete(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.issueId, issueId),
        ),
      )
      .run();
    tx.delete(comments)
      .where(
        and(orgPredicate(comments.orgId, orgId), eq(comments.issueId, issueId)),
      )
      .run();
    tx.delete(attachments)
      .where(
        and(
          orgPredicate(attachments.orgId, orgId),
          eq(attachments.issueId, issueId),
        ),
      )
      .run();
    tx.delete(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .run();

    return {
      commentIds: commentRows.map((c) => c.id),
      attachmentSizes: attachmentRows.map((a) => a.sizeBytes),
    };
  });
}
