/**
 * Takes an issue back out of the trash. Archived issues live for the plan's
 * `retentionDays`; past that they are expired and only await the purge.
 */
export async function restoreIssue(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<Issue> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:archive", issueResource(issue));

  if (!isArchived(issue) || issue.archivedAt === null) {
    throw new RestoreRefusedError("not_archived", "Issue", issue.id);
  }

  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  const { retentionDays } = getPlanLimits(org.plan);
  const archivedAt = new Date(issue.archivedAt).getTime();
  if (Date.now() - archivedAt >= retentionDays * MS_PER_DAY) {
    throw new RestoreRefusedError("expired", "Issue", issue.id);
  }

  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  if (!project || isArchived(project)) {
    throw new RestoreRefusedError("project_archived", "Issue", issue.id);
  }

  const used = await issueRepo.countIssues(orgId, issue.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
    throw new RestoreRefusedError("quota", "Issue", issue.id);
  }

  const restored = await issueRepo.restoreIssue(orgId, issueId);

  await emit("issue.restored", {
    ...actorEnvelope(actor),
    issueId: restored.id,
    projectId: restored.projectId,
  });

  return restored;
}

/**
 * Board drag-and-drop.''')
